-- ข้อมูลตั้งต้น (รันหลัง schema.sql เพียงครั้งเดียว)
-- ศดปช. 15 · ศจช. 29 · แปลงพยากรณ์ 99 · คลินิกพืช 12
-- ป้องกันการรันซ้ำ: จะไม่เพิ่มถ้ามีข้อมูลอยู่แล้ว
do $$ begin
if exists (select 1 from public.sites limit 1) then raise notice 'มีข้อมูลอยู่แล้ว ข้ามการนำเข้า'; return; end if;
end $$;

on conflict (key) do nothing;
